  test('create-claim-payment (1)', async () => {
    const server = mockServerPool.createServer();
    const client = new PaywiseClient({
      maxRetries: 0,
      token: 'test',
      onBehalfOfCompany: 'test',
      environment: server.baseUrl,
    });
    const rawRequestBody = {
      amount: { currency: 'EUR', value: '50.00' },
      metadata: [{ type: 'transaction:reference', value: 'BANK-TRANSACTION-99812' }],
      value_date: '2026-07-17',
      your_reference: 'BANK-TRANSACTION-99812',
    };
    const rawResponseBody = {
      amount: { currency: 'currency', value: 'value' },
      claim: {
        document_reference: 'document_reference',
        id: 'id',
        your_reference: 'your_reference',
      },
      created_at: '2024-01-15T09:30:00Z',
      id: 'id',
      mandate: { id: 'id', reference_number: 'reference_number' },
      metadata: [{ type: 'type', value: 'value' }],
      updated_at: '2024-01-15T09:30:00Z',
      value_date: '2023-01-15',
      your_reference: 'your_reference',
    };

    server
      .mockEndpoint()
      .post('/v2/claims/claim_id/payments/')
      .header('Idempotency-Key', 'Idempotency-Key')
      .jsonBody(rawRequestBody)
      .respondWith()
      .statusCode(200)
      .jsonBody(rawResponseBody)
      .build();

    const response = await client.caseManagement.claims.createClaimPayment({
      'Idempotency-Key': 'Idempotency-Key',
      claim_id: 'claim_id',
      body: {
        amount: {
          currency: 'EUR',
          value: '50.00',
        },
        metadata: [
          {
            type: 'transaction:reference',
            value: 'BANK-TRANSACTION-99812',
          },
        ],
        value_date: '2026-07-17',
        your_reference: 'BANK-TRANSACTION-99812',
      },
    });
    expect(response).toEqual(rawResponseBody);
  });

